mapper.select:
select a.id, a.name, a.start_time, a.end_time, a.status, a.create_time, a.update_time, ( select count(1) from seckill_sku s where s.activity_id = a.id and s.is_deleted = 0 ) as sku_count from seckill_activity a where a.is_deleted = 0
and a.status = #{status}
order by a.create_time desc, a.id desc

mapper.update:
update seckill_activity
set status = #{targetStatus}, update_time = now()
where id = #{id}
  and status = #{expectedStatus}
  and is_deleted = 0
